 "a21-x1-s": {
  "stufe": "a21",
  "title": "A2.1 Zusatz · Wetter & Jahreszeiten — Sätze",
  "cards": [
   {
    "hanzi": "今天比昨天冷。",
    "pinyin": "Jīntiān bǐ zuótiān lěng.",
    "de": "Heute ist es kälter als gestern.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "我最喜欢春天，因为不冷也不热。",
    "pinyin": "Wǒ zuì xǐhuan chūntiān, yīnwèi bù lěng yě bù rè.",
    "de": "Ich mag den Frühling am liebsten, weil es weder kalt noch heiß ist.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "你看天气预报了吗？",
    "pinyin": "Nǐ kàn tiānqì yùbào le ma?",
    "de": "Hast du den Wetterbericht gesehen?",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "明天有雨，出门别忘了带雨伞。",
    "pinyin": "Míngtiān yǒu yǔ, chūmén bié wàng le dài yǔsǎn.",
    "de": "Morgen regnet es, vergiss beim Rausgehen den Regenschirm nicht.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "因为今天刮风，所以我们不去公园了。",
    "pinyin": "Yīnwèi jīntiān guāfēng, suǒyǐ wǒmen bù qù gōngyuán le.",
    "de": "Weil es heute windig ist, gehen wir nicht in den Park.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "维也纳的冬天常常下雪。",
    "pinyin": "Wéiyěnà de dōngtiān chángcháng xià xuě.",
    "de": "In Wien schneit es im Winter oft.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "外面多少度？",
    "pinyin": "Wàimiàn duōshao dù?",
    "de": "Wie viel Grad hat es draußen?",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "我去过哈尔滨，那里冬天零下二十度。",
    "pinyin": "Wǒ qù guo Hā'ěrbīn, nàlǐ dōngtiān língxià èrshí dù.",
    "de": "Ich war in Harbin, dort hat es im Winter minus zwanzig Grad.",
    "level": "schwer",
    "type": "satz"
   },
   {
    "hanzi": "下雪以后，天气更冷了。",
    "pinyin": "Xià xuě yǐhòu, tiānqì gèng lěng le.",
    "de": "Nach dem Schneefall ist es noch kälter geworden.",
    "level": "schwer",
    "type": "satz"
   },
   {
    "hanzi": "今天是晴天，阳光很好，我们去散步吧。",
    "pinyin": "Jīntiān shì qíngtiān, yángguāng hěn hǎo, wǒmen qù sànbù ba.",
    "de": "Heute ist es sonnig, lass uns spazieren gehen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "这里夏天很潮湿，我不太习惯。",
    "pinyin": "Zhèlǐ xiàtiān hěn cháoshī, wǒ bú tài xíguàn.",
    "de": "Hier ist es im Sommer sehr feucht, ich bin es nicht gewohnt.",
    "level": "schwer",
    "type": "satz"
   }
  ]
 },
