 "a21-x4-s": {
  "stufe": "a21",
  "title": "A2.1 Zusatz · Gesundheit & Arzt — Sätze",
  "cards": [
   {
    "hanzi": "你哪里不舒服？",
    "pinyin": "Nǐ nǎlǐ bù shūfu?",
    "de": "Wo fehlt es dir?",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "我头疼，还有点儿发烧。",
    "pinyin": "Wǒ tóu téng, hái yǒudiǎnr fāshāo.",
    "de": "Ich habe Kopfschmerzen und etwas Fieber.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我咳嗽了三天，嗓子也很疼。",
    "pinyin": "Wǒ késou le sān tiān, sǎngzi yě hěn téng.",
    "de": "Ich huste seit drei Tagen und der Hals tut auch weh.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我昨天吃了不干净的东西，所以今天拉肚子。",
    "pinyin": "Wǒ zuótiān chī le bù gānjìng de dōngxi, suǒyǐ jīntiān lā dùzi.",
    "de": "Gestern habe ich etwas Verdorbenes gegessen, deshalb habe ich heute Durchfall.",
    "level": "schwer",
    "type": "satz"
   },
   {
    "hanzi": "你最好去医院看看。",
    "pinyin": "Nǐ zuìhǎo qù yīyuàn kànkan.",
    "de": "Du gehst am besten mal ins Krankenhaus.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "先挂号，然后在外面等一下。",
    "pinyin": "Xiān guàhào, ránhòu zài wàimiàn děng yíxià.",
    "de": "Erst anmelden, dann draußen kurz warten.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "医生说我感冒了，不太严重。",
    "pinyin": "Yīshēng shuō wǒ gǎnmào le, bú tài yánzhòng.",
    "de": "Der Arzt sagt, ich habe mich erkältet, aber nicht schlimm.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "这个药一天吃三次，一次两片。",
    "pinyin": "Zhè ge yào yì tiān chī sān cì, yí cì liǎng piàn.",
    "de": "Dieses Medikament dreimal täglich, zwei Tabletten auf einmal.",
    "level": "schwer",
    "type": "satz"
   },
   {
    "hanzi": "你要多喝水，多休息。",
    "pinyin": "Nǐ yào duō hē shuǐ, duō xiūxi.",
    "de": "Du musst viel Wasser trinken und dich viel ausruhen.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "吃药以后，你好一点儿了吗？",
    "pinyin": "Chī yào yǐhòu, nǐ hǎo yìdiǎnr le ma?",
    "de": "Geht es dir nach der Medizin etwas besser?",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我对花粉过敏，春天常常打喷嚏。",
    "pinyin": "Wǒ duì huāfěn guòmǐn, chūntiān chángcháng dǎ pēntì.",
    "de": "Ich bin allergisch gegen Pollen und niese im Frühling oft.",
    "level": "schwer",
    "type": "satz"
   },
   {
    "hanzi": "别太累了，注意身体。",
    "pinyin": "Bié tài lèi le, zhùyì shēntǐ.",
    "de": "Überanstreng dich nicht, achte auf deine Gesundheit.",
    "level": "mittel",
    "type": "satz"
   }
  ]
 },
