 "a22-y3-s": {
  "stufe": "a22",
  "title": "A2.2 · Können, Wollen, Müssen & Bitten — Sätze",
  "cards": [
   {
    "hanzi": "你应该早点睡觉。",
    "pinyin": "Nǐ yīnggāi zǎodiǎn shuìjiào.",
    "de": "Du solltest früher schlafen gehen.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "你必须带护照才能上飞机。",
    "pinyin": "Nǐ bìxū dài hùzhào cái néng shàng fēijī.",
    "de": "Du musst deinen Reisepass dabeihaben, um ins Flugzeug zu dürfen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我愿意帮你搬家。",
    "pinyin": "Wǒ yuànyì bāng nǐ bānjiā.",
    "de": "Ich helfe dir gern beim Umzug.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "老板让我明天早点来。",
    "pinyin": "Lǎobǎn ràng wǒ míngtiān zǎodiǎn lái.",
    "de": "Der Chef hat mich gebeten, morgen früher zu kommen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "请你帮我拿一下行李。",
    "pinyin": "Qǐng nǐ bāng wǒ ná yíxià xíngli.",
    "de": "Bitte hilf mir kurz mit dem Gepäck.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "医生不允许我喝酒。",
    "pinyin": "Yīshēng bù yǔnxǔ wǒ hējiǔ.",
    "de": "Der Arzt erlaubt mir nicht, Alkohol zu trinken.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "他不敢一个人去。",
    "pinyin": "Tā bù gǎn yí gè rén qù.",
    "de": "Er traut sich nicht, allein zu gehen.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "我得走了，明天还要早起。",
    "pinyin": "Wǒ děi zǒu le, míngtiān hái yào zǎo qǐ.",
    "de": "Ich muss los, morgen muss ich noch früh aufstehen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "你能不能小声一点？",
    "pinyin": "Nǐ néng bu néng xiǎoshēng yìdiǎn?",
    "de": "Kannst du bitte etwas leiser sein?",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "这件事你需要问经理。",
    "pinyin": "Zhè jiàn shì nǐ xūyào wèn jīnglǐ.",
    "de": "In dieser Sache musst du den Manager fragen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "对不起，麻烦你再说一遍。",
    "pinyin": "Duìbuqǐ, máfan nǐ zài shuō yí biàn.",
    "de": "Entschuldigung, könnten Sie es bitte noch einmal sagen?",
    "level": "mittel",
    "type": "satz"
   }
  ]
 },
