 "a22-y4-s": {
  "stufe": "a22",
  "title": "A2.2 · Essen, Gastgeber & Restaurant 2 — Sätze",
  "cards": [
   {
    "hanzi": "今天我请客，你们随便点。",
    "pinyin": "Jīntiān wǒ qǐngkè, nǐmen suíbiàn diǎn.",
    "de": "Heute lade ich euch ein, bestellt, was ihr wollt.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "服务员，请给我们菜单。",
    "pinyin": "Fúwùyuán, qǐng gěi wǒmen càidān.",
    "de": "Bitte bringen Sie uns die Speisekarte.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "这个菜太咸了，能不能换一个？",
    "pinyin": "Zhège cài tài xián le, néng bu néng huàn yí gè?",
    "de": "Dieses Gericht ist zu salzig, können wir ein anderes nehmen?",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我不要辣的，请做清淡一点。",
    "pinyin": "Wǒ bú yào là de, qǐng zuò qīngdàn yìdiǎn.",
    "de": "Ich möchte nichts Scharfes, bitte machen Sie es milder.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我们点多了，吃不完，请帮我们打包。",
    "pinyin": "Wǒmen diǎn duō le, chī bu wán, qǐng bāng wǒmen dǎbāo.",
    "de": "Wir haben zu viel bestellt und schaffen es nicht, bitte packen Sie es uns ein.",
    "level": "schwer",
    "type": "satz"
   },
   {
    "hanzi": "服务员，我们要买单。",
    "pinyin": "Fúwùyuán, wǒmen yào mǎidān.",
    "de": "Wir möchten zahlen.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "可以开发票吗？",
    "pinyin": "Kěyǐ kāi fāpiào ma?",
    "de": "Können Sie mir eine Rechnung ausstellen?",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "这道菜是我们的招牌菜。",
    "pinyin": "Zhè dào cài shì wǒmen de zhāopáicài.",
    "de": "Dieses Gericht ist unsere Spezialität.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "欢迎来我家做客，别客气。",
    "pinyin": "Huānyíng lái wǒ jiā zuòkè, bié kèqi.",
    "de": "Willkommen bei mir zu Hause, seid nicht schüchtern.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "干杯！祝大家身体健康。",
    "pinyin": "Gānbēi! Zhù dàjiā shēntǐ jiànkāng.",
    "de": "Prost! Auf die Gesundheit aller.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "请问有没有包间？",
    "pinyin": "Qǐngwèn yǒu méiyǒu bāojiān?",
    "de": "Gibt es ein separates Zimmer?",
    "level": "mittel",
    "type": "satz"
   }
  ]
 },
