 "a22-y6-s": {
  "stufe": "a22",
  "title": "A2.2 · Gründe, Meinungen & Gefühle — Sätze",
  "cards": [
   {
    "hanzi": "因为下雨，所以我们不去公园了。",
    "pinyin": "Yīnwèi xiàyǔ, suǒyǐ wǒmen bú qù gōngyuán le.",
    "de": "Weil es regnet, gehen wir nicht in den Park.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "虽然很累，但是我今天很开心。",
    "pinyin": "Suīrán hěn lèi, dànshì wǒ jīntiān hěn kāixīn.",
    "de": "Obwohl ich müde bin, bin ich heute glücklich.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我觉得这个办法不太好。",
    "pinyin": "Wǒ juéde zhège bànfǎ bú tài hǎo.",
    "de": "Ich finde, diese Lösung ist nicht so gut.",
    "level": "leicht",
    "type": "satz"
   },
   {
    "hanzi": "你认为我们应该怎么做？",
    "pinyin": "Nǐ rènwéi wǒmen yīnggāi zěnme zuò?",
    "de": "Was sollten wir deiner Meinung nach tun?",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我同意你说的，不过我有一点儿担心。",
    "pinyin": "Wǒ tóngyì nǐ shuō de, búguò wǒ yǒu yìdiǎnr dānxīn.",
    "de": "Ich stimme dir zu, aber ich mache mir ein wenig Sorgen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "对不起，这件事我不能同意。",
    "pinyin": "Duìbuqǐ, zhè jiàn shì wǒ bù néng tóngyì.",
    "de": "Tut mir leid, dem kann ich nicht zustimmen.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "明天面试，我现在特别紧张。",
    "pinyin": "Míngtiān miànshì, wǒ xiànzài tèbié jǐnzhāng.",
    "de": "Morgen ist das Vorstellungsgespräch, ich bin gerade sehr nervös.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "你别难过了，一切都会好的。",
    "pinyin": "Nǐ bié nánguò le, yíqiè dōu huì hǎo de.",
    "de": "Sei nicht traurig, es wird alles gut.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "我对这家酒店不太满意。",
    "pinyin": "Wǒ duì zhè jiā jiǔdiàn bú tài mǎnyì.",
    "de": "Mit diesem Hotel bin ich nicht so zufrieden.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "其实我也这么想，你说得对。",
    "pinyin": "Qíshí wǒ yě zhème xiǎng, nǐ shuō de duì.",
    "de": "Eigentlich denke ich das auch, du hast recht.",
    "level": "mittel",
    "type": "satz"
   },
   {
    "hanzi": "你放心，我一定会准时到的。",
    "pinyin": "Nǐ fàngxīn, wǒ yídìng huì zhǔnshí dào de.",
    "de": "Keine Sorge, ich komme bestimmt pünktlich.",
    "level": "mittel",
    "type": "satz"
   }
  ]
 },
